<script setup lang="ts">
import { requestAbort } from './request-abort';
import{visitEntry,type VisitEntry}from'./use-visit-handoff';
import{ref,computed,watch,onMounted,onUnmounted}from'vue';import{useCareQueue}from'./use-care-queue';import{useCareCommand}from'./use-care-command';import ImageHistoryPanel from'./ImageHistoryPanel.vue';import LabHistoryPanel from'./LabHistoryPanel.vue';import{ImagePlus,FlaskConical,RefreshCw,ArrowLeft,X,Plus,Check,Download,Eye}from'@lucide/vue';
const props=defineProps<{staff:any;visitEntry?:VisitEntry|null}>(),emit=defineEmits(['unauthorized','return-clinical']);const clinics=ref<any[]>([]),clinic=ref(''),date=ref(''),functions=ref<string[]>([]),detail=ref<any>(null),loading=ref(false),ready=ref(false),mode=ref(''),form=ref<any>({}),file=ref<File|null>(null),previewUrl=ref(''),previewVerified=ref(false),uploadRequest=ref('');
const scopeCapabilities=ref<Record<string,any>>({});let detailGeneration=0,previewGeneration=0,initGeneration=0;
const queue=useCareQueue({account:()=>props.staff,clinic:()=>clinic.value,date:()=>date.value,read:(path,signal)=>request(path,undefined,false,signal),invalidated:status=>{clearPrivate();if(status===401)emit('unauthorized');}}),rows=queue.items;
const currentCapability=computed(()=>queue.capabilities.value||scopeCapabilities.value[clinic.value]||{}),has=(f:string)=>detail.value?detail.value.functions.includes(f):!!currentCapability.value[({'image.read':'imageRead','lab.read':'labRead','image.photo':'photo','image.scan':'scan','lab.request':'request','lab.review':'review','lab.handover':'handover','lab.progress':'progress','lab.problem':'problem'}as Record<string,string>)[f]],canUpload=computed(()=>has('image.photo')||has('image.scan')),local=(s?:string)=>new Date((s?Date.parse(s):Date.now())+8*3600000).toISOString().slice(0,19),instant=(s:string)=>s?new Date(s+'+08:00').toISOString():null,full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const targets=useCareQueue({account:()=>props.staff,clinic:()=>clinic.value,date:()=>date.value,read:(path,signal)=>request(path,undefined,false,signal),invalidated:status=>{if(status===401||status===403){clearPrivate();if(status===401)emit('unauthorized');}}});
const command=useCareCommand({owner:()=>props.staff,storage:()=>sessionStorage,read:path=>request(path),send:(path,body)=>request(path,body),completed:async()=>{mode.value='';clearPreview();await refresh();}}),{pending,busy,error,notice}=command;
let alive=true;const actorKey=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]);
async function findTargets(more=false){if(!more){form.value.targetVisitId=detail.value?.visit.id;form.value.identityConfirmed=false;}await targets.load(more);}
const stateText:any={awaiting_receipt:'正确接收依据未齐',awaiting_review:'已正确接收 · 待临床核对',usable:'当前临床核对可用',requirement_changed:'治疗依据已变 · 待更新要求'};
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function request(path:string,body?:any,binary=false,signal?:AbortSignal){const owner=actorKey(),abort=requestAbort(15000,signal);try{const r=await fetch('/api/v1/care'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body?JSON.stringify(body):undefined,signal:abort.signal});if(!r.ok){const b=await r.json().catch(()=>({}));if(r.status===401&&alive&&owner===actorKey())emit('unauthorized');throw new ApiError(r.status,b.message||'请求失败，请重新核对。');}return binary?r.blob():r.json();}finally{abort.dispose();}}
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';
function clearPrivate(){detailGeneration++;detail.value=null;mode.value='';form.value={};file.value=null;clearPreview();targets?.reset();}
const readContext=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId,clinic.value,date.value,detail.value?.visit.id]);
function clearPreview(){previewGeneration++;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewVerified.value=false;}
async function preview(path:string){clearPreview();const gen=previewGeneration,key=readContext(),blob=await request(path,undefined,true);if(gen!==previewGeneration||key!==readContext()||!mode.value)return;previewUrl.value=URL.createObjectURL(blob);previewVerified.value=true;}
async function initialize(){const gen=++initGeneration,account=props.staff?.accountId;loading.value=true;try{command.restore();const b=await request('/bootstrap');if(gen!==initGeneration||props.staff?.accountId!==account)return;functions.value=b.functions;scopeCapabilities.value=b.capabilities;clinics.value=b.clinics;const target=props.visitEntry?visitEntry(props.visitEntry,props.staff):null;if(target&&!b.clinics.some((c:any)=>c.id===target.clinicId))throw Error('当前没有交接就诊所属诊所的工作范围。');clinic.value=target?.clinicId||b.clinics[0]?.id||'';date.value=target?.date||b.today;ready.value=true;await refresh();if(target&&gen===initGeneration&&props.staff?.accountId===account)await openHandoff();}catch(e){if(gen===initGeneration)error.value=explain(e);}finally{if(gen===initGeneration)loading.value=false;}}
async function refresh(){if(!ready.value)return initialize();if(!clinic.value)return;const selected=detail.value?.visit.id,key=readContext();if(queue.dirty.value)clearPrivate();loading.value=true;if(!pending.value&&!command.isBlocked())error.value='';try{const ok=await queue.load();if(ok&&selected&&key===readContext())await select(selected);}finally{loading.value=false;}}
async function select(id:string){const gen=++detailGeneration,key=readContext();try{error.value='';const r=await request('/visits/'+id);if(gen===detailGeneration&&key===readContext()){if(r.visit?.id!==id||(props.visitEntry&&id===props.visitEntry.visitId&&r.visit?.clinicId!==props.visitEntry.clinicId))throw Error('交接就诊与当前诊所不一致，未显示内容。');detail.value=r;}}catch(e){if(gen===detailGeneration&&key===readContext()){clearPrivate();error.value=explain(e);}}}
async function query(){clearPrivate();await queue.load();}async function clearFilters(){clearPrivate();await queue.clearFilters();}
watch(()=>[props.staff?.accountId,props.staff?.employeeId],()=>{initGeneration++;clearPrivate();scopeCapabilities.value={};functions.value=[];clinics.value=[];ready.value=false;},{flush:'sync'});
async function open(m:string,data?:any){if(pending.value){error.value='请先核实原提交。';return;}clearPreview();targets.reset();mode.value=m;error.value='';file.value=null;const d=detail.value;
 if(m==='image'){uploadRequest.value=crypto.randomUUID();form.value={imageId:data?.image_id||null,version:data?Number(data.row_version):0,fileId:data?.file_id||'',targetVisitId:d.visit.id,imageType:data?.image_type||(has('image.scan')?'scan':'photo'),formedAt:local(data?.formed_at||d.visit.arrivedAt),description:data?.description||'',identityConfirmed:false,duplicateConfirmed:false,reason:''};if(data)try{await preview('/images/'+data.image_id+'/content');}catch(e){error.value=explain(e);}}
 if(m==='prepared'){mode.value='image';uploadRequest.value=crypto.randomUUID();form.value={imageId:null,version:0,fileId:data.file_id,targetVisitId:d.visit.id,imageType:has('image.scan')?'scan':'photo',formedAt:local(d.visit.arrivedAt),description:'',identityConfirmed:false,duplicateConfirmed:false,reason:''};try{await preview(`/visits/${d.visit.id}/files/${data.file_id}`);}catch(e){error.value=explain(e);}}
 if(m==='preview'){form.value={imageId:data.image_id};try{await preview('/images/'+data.image_id+'/content');}catch(e){error.value=explain(e);}}
 if(m==='requirement'){const t=d.treatments.find((t:any)=>t.id===data?.treatment_id);form.value={orderId:data?.lab_order_id||null,version:data?.version||0,treatmentId:t?.id||'',labParty:data?.lab_party||'',requirementText:data?.requirement?.requirement_text||'',expectedReturnAt:data?.current_expected_return_at?local(data.current_expected_return_at):'',reason:''};}
 if(m==='lab'){form.value={order:data,action:'',content:'',occurredAt:local(),matchesRequirement:'unknown',expectedReturnAt:data.current_expected_return_at?local(data.current_expected_return_at):'',isUsable:'',resolveIssues:false,resolution:'',invalidateReceipt:false};}
}
function historyDenied(status:number){clearPrivate();if(status===401)emit('unauthorized');else error.value='当前已无此就诊的相应供阅权限，请重新读取工作范围。';}
function close(){if(!busy.value&&!pending.value){mode.value='';clearPreview();}}
function selectedFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;form.value.fileId='';form.value.identityConfirmed=false;uploadRequest.value=crypto.randomUUID();clearPreview();}
async function prepare(){if(!file.value||busy.value||pending.value)return;const owner=actorKey(),context=readContext(),originalForm=form.value,originalFile=file.value,requestId=uploadRequest.value,valid=()=>alive&&context===readContext()&&form.value===originalForm;busy.value=true;error.value='';try{const data=new FormData();data.append('requestId',requestId);data.append('file',originalFile);const r=await request(`/visits/${originalForm.targetVisitId}/files`,data);if(!valid())return;originalForm.fileId=r.id;await preview(`/visits/${originalForm.targetVisitId}/files/${r.id}`);if(valid()&&previewVerified.value)notice.value='文件已准备并读取，请核对预览和归档对象后确认。';}catch(e){if(valid())error.value=e instanceof ApiError?e.message:'文件准备结果暂不明确，可保持原文件重试；重载后也可检查待归档准备列表。';}finally{if(alive&&owner===actorKey()&&!pending.value)busy.value=false;}}
async function send(path:string,body:any,label:string){const result=await command.submit(path,body);if(pending.value){mode.value='';clearPreview();}return result;}
async function save(){const f=form.value,d=detail.value,requestId=crypto.randomUUID();try{
 if(mode.value==='image'){if(!f.fileId||!previewVerified.value){error.value='须先准备并成功读取文件预览。';return;}return send(`/visits/${f.targetVisitId}/images`,{requestId,imageId:f.imageId,version:f.version,fileId:f.fileId,imageType:f.imageType,formedAt:instant(f.formedAt),description:f.description||null,identityConfirmed:f.identityConfirmed,duplicateConfirmed:f.duplicateConfirmed,reason:f.reason||null},'影像归档已保存，当前目录按新关联显示。');}
 if(mode.value==='requirement'){const t=d.treatments.find((x:any)=>x.id===f.treatmentId);if(!t)throw Error('请选择有效实际治疗。');return send(`/visits/${d.visit.id}/requirements`,{requestId,orderId:f.orderId,version:f.version,treatmentId:t.id,treatmentVersion:t.version,labParty:f.labParty,requirementText:f.requirementText,expectedReturnAt:instant(f.expectedReturnAt),reason:f.reason||null},'医生加工要求已保存；后续交接和核对采用本版要求。');}
 if(mode.value==='lab'){const o=f.order;return send(`/labs/${o.lab_order_id}/actions`,{requestId,version:o.version,requirementId:o.requirement.requirement_id,action:f.action,content:f.content,occurredAt:['sent','received','review'].includes(f.action)?instant(f.occurredAt):null,matchesRequirement:f.action==='received'?f.matchesRequirement==='unknown'?null:f.matchesRequirement==='yes':null,expectedReturnAt:f.action==='progress'?instant(f.expectedReturnAt):null,receivedId:f.action==='review'?o.current_received_handover_id:null,isUsable:f.action==='review'?f.isUsable==='yes':false,resolveIssues:f.resolveIssues,resolution:f.resolution||null,invalidateReceipt:f.invalidateReceipt},'加工阶段及历史已保存；可用性按当前要求、接收和医生核对确定。');}
 }catch(e){error.value=explain(e);}}
async function download(id:string){const owner=actorKey(),context=readContext();busy.value=true;try{const blob=await request('/images/'+id+'/content',undefined,true);if(context!==readContext())return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ADC-影像-'+id.slice(0,8)+(blob.type==='image/png'?'.png':'.jpg');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){if(alive&&context===readContext())error.value=explain(e);}finally{if(alive&&owner===actorKey()&&!pending.value)busy.value=false;}}
async function openHandoff(){if(!props.visitEntry||busy.value||pending.value||mode.value||command.isBlocked())return;const e=visitEntry(props.visitEntry,props.staff);if(clinic.value!==e.clinicId||date.value!==e.date){error.value='交接范围已改变，请返回原诊所和日期后重读。';return;}await select(e.visitId);}
function returnClinical(){if(!busy.value&&!loading.value&&!pending.value&&!mode.value&&!command.isBlocked())emit('return-clinical');}
onMounted(initialize);onUnmounted(()=>{alive=false;initGeneration++;clearPrivate();});defineExpose({refresh});
</script>
<template><div class="care-workspace"><div v-if="props.visitEntry" class="b-card"><p>由诊疗详情定位同次就诊，影像与加工仍按当前权限供阅。</p><button class="b-button outline small" :disabled="busy||loading||!!pending||!!mode||command.isBlocked()" @click="openHandoff">重读交接就诊</button><button class="b-button outline small" :disabled="busy||loading||!!pending||!!mode||command.isBlocked()" @click="returnClinical">返回原诊疗就诊</button></div>
 <div v-if="error" class="b-alert error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="b-alert success" role="status"><Check :size="17"/>{{notice}}<button @click="notice=''">关闭</button></div><div v-if="pending" class="b-alert warning" role="status"><span>{{pending.summary}} · {{pending.phase==='confirmed'?'业务已成功，仅本机提示待清理':pending.phase==='rejected'?'办理已被拒绝，仅本机提示待清理':'原提交结果待核实'}}</span><button v-if="pending.phase==='pending'" class="b-button small" :disabled="busy" @click="command.verify()">只读核实原结果</button><button v-if="pending.phase==='pending'" class="b-button small" :disabled="busy" @click="command.retry()">重试原提交</button><button v-else class="b-button small" :disabled="busy" @click="command.cleanup()">清理本机提示</button></div>
 <div v-if="pending&&command.status.value" class="b-card care-recovery"><template v-if="command.status.value.state==='completed'"><strong>原请求已有成功办理记录</strong><p>结果 {{command.status.value.resultId.slice(0,8).toUpperCase()}} · 原结果版本 {{command.status.value.version}} · 保存时间 {{full(command.status.value.completedAt)}}</p><p>这里核实的是原请求ID对应的结果，不表示后来状态或当前表单内容。请核对原记录后清理提示。</p><button class="b-button outline small" :disabled="busy" @click="command.acknowledge()">已核对原结果，清理提示</button></template><template v-else><strong>暂未查到已完成记录</strong><p>可能仍在处理中，也可能未提交成功。此次查询没有重新办理，可稍后再次核实；如需重试，请只用上方原请求。</p></template></div>
 <div class="b-card f-toolbar"><label>诊所<select v-model="clinic" @change="refresh" :disabled="busy||!!pending"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>实际到院日期<input type="date" v-model="date" @change="refresh" :disabled="busy||!!pending"/></label><button class="b-button outline small" :disabled="loading" @click="refresh"><RefreshCw :size="15"/>刷新</button></div>
 <div v-if="!ready" class="b-card b-empty">{{loading?'正在连接…':'未取得工作范围'}}<button class="b-button outline" :disabled="loading" @click="initialize">重新连接</button></div><div v-else-if="!clinics.length" class="b-card b-empty">当前账号没有影像或加工工作范围。</div>
 <section v-else-if="!detail" class="care-queue">
 <div class="b-card care-queue-filters"><label>患者姓名<input v-model="queue.search.value" maxlength="100" placeholder="按姓名检索" @keydown.enter.prevent="query"/></label><label>接诊医生<select v-model="queue.doctorId.value"><option value="">全部授权医生</option><option v-for="d in queue.doctors.value" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label v-if="currentCapability.imageRead">影像归档<select v-model="queue.image.value"><option value="all">全部归档情况</option><option value="has">已有影像归档</option><option value="none">尚无影像归档</option></select></label><label v-if="currentCapability.labRead">加工情况<select v-model="queue.lab.value"><option value="all">全部加工情况</option><option value="none">尚无加工订单</option><option value="has">已有加工订单</option><option value="awaiting_receipt">正确接收依据未齐</option><option value="awaiting_review">待临床核对</option><option value="usable">有临床可用核对</option><option value="requirement_changed">治疗依据已变</option><option value="issues">有未解可用性问题</option></select></label><label>每页就诊<select v-model.number="queue.limit.value"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><div class="care-actions"><button class="b-button" :disabled="queue.loading.value||busy||!!pending" @click="query">查询就诊</button><button class="b-button outline" :disabled="queue.loading.value||busy||!!pending" @click="clearFilters">清空筛选</button></div><p v-if="queue.dirty.value" class="care-queue-note">筛选条件已改变，请查询后再打开办理。</p><p class="care-queue-note">已显示 {{rows.length}} / {{queue.total.value}} 次 · 读取时点 {{full(queue.asOf.value)}}。统计覆盖当前日期、姓名和医生的完整授权范围，不随归档、加工筛选及分页缩小。</p><p v-if="queue.error.value" class="b-alert error" role="alert">{{queue.error.value}}</p></div>
 <div class="care-queue-overview"><div class="b-card"><strong>{{queue.summary.value?.total??'—'}}</strong><span>范围内就诊</span></div><div v-if="currentCapability.imageRead" class="b-card"><strong>{{queue.summary.value?.image.has??'—'}}</strong><span>有影像归档的就诊</span></div><div v-if="currentCapability.labRead" class="b-card"><strong>{{queue.summary.value?.lab.has??'—'}}</strong><span>有加工订单的就诊</span></div><div v-if="currentCapability.labRead" class="b-card"><strong>{{queue.summary.value?.lab.issues??'—'}}</strong><span>有未解加工问题的就诊</span></div></div>
 <p class="care-queue-note" v-if="queue.summary.value"><template v-if="currentCapability.imageRead">影像供阅 {{queue.summary.value.image.available}} 次：尚无归档 {{queue.summary.value.image.none}} 次。归档不代表文件当前可读取。</template><template v-if="currentCapability.labRead">加工供阅 {{queue.summary.value.lab.available}} 次：无订单 {{queue.summary.value.lab.none}} · 接收依据未齐 {{queue.summary.value.lab.awaiting_receipt}} · 待临床核对 {{queue.summary.value.lab.awaiting_review}} · 有可用核对 {{queue.summary.value.lab.usable}} · 治疗依据已变 {{queue.summary.value.lab.requirement_changed}}。同一次就诊可有不同状态的多笔订单，以上次数不能相加；收到加工件也不代表已装戴。</template></p>
 <div class="b-card f-list care-queue-list"><div class="f-list-head"><div><h2>实际就诊的影像与加工</h2><p>核对患者和原就诊后办理，影像与加工按各自权限供阅。</p></div></div><div class="b-table-scroll"><table><thead><tr><th>患者 / 到院时间</th><th>接诊医生</th><th v-if="currentCapability.imageRead">影像归档</th><th v-if="currentCapability.labRead">加工订单</th><th>操作</th></tr></thead><tbody><tr v-for="v in rows" :key="v.id"><td><strong>{{v.patientName}}</strong><small>{{full(v.arrivedAt)}}</small><small>就诊 {{v.id.slice(0,8).toUpperCase()}}</small></td><td>{{v.doctorName}}</td><td v-if="currentCapability.imageRead">{{v.canImage?v.imageCount+' 项':'不在供阅范围'}}</td><td v-if="currentCapability.labRead"><template v-if="v.canLab">{{v.labTotal}} 笔<small v-if="v.labIssues">未解问题 {{v.labIssues}} 笔</small></template><template v-else>不在供阅范围</template></td><td><button class="b-button outline small" :disabled="queue.loading.value||queue.dirty.value||busy||!!pending" @click="select(v.id)">打开影像与加工</button></td></tr><tr v-if="!rows.length"><td colspan="5" class="b-empty">{{queue.loading.value?'正在读取…':'当前条件下没有授权就诊。'}}</td></tr></tbody></table></div><button v-if="queue.next.value" class="b-button outline" :disabled="queue.loading.value||queue.dirty.value||busy||!!pending" @click="queue.load(true)">继续加载就诊</button></div></section>
 <template v-else><button class="c-back" @click="clearPrivate"><ArrowLeft :size="16"/>返回实际就诊</button><section class="b-card c-patient"><div><h2>{{detail.visit.patientName}}</h2><p>{{detail.visit.doctorName}} · 实际到院 {{full(detail.visit.arrivedAt)}}</p></div><span class="b-pill">影像与加工分别留痕</span></section>
 <section v-if="has('image.read')" class="b-card c-block"><div class="f-list-head"><div><h2><ImagePlus :size="19"/>诊疗影像与照片</h2><p>仅当前归档目录。点击查看时校验文件及当前权限。</p></div><button v-if="canUpload" class="b-button small" :disabled="busy||!!pending" @click="open('image')">准备并归档影像</button></div><div class="care-images"><article v-for="i in detail.images" :key="i.image_id" class="care-image-card"><div><span class="b-pill">{{i.image_type==='scan'?'检查影像':'诊疗照片'}}</span><small>版本 {{i.row_version}} · {{Math.ceil(Number(i.byte_size)/1024)}} KB</small></div><strong>{{full(i.formed_at)}} 形成</strong><p>{{i.description||'未填附加说明'}}</p><div class="care-actions"><button class="b-button outline small" @click="open('preview',i)"><Eye :size="14"/>查看</button><button class="b-button outline small" :disabled="busy" @click="download(i.image_id)"><Download :size="14"/>下载</button><button v-if="(i.image_type==='photo'&&has('image.photo'))||(i.image_type==='scan'&&has('image.scan'))" class="f-text" @click="open('image',i)">更正归档</button></div></article><p v-if="!detail.images.length" class="b-help">当前无已确认归档的影像。准备文件尚不表示归档完成。</p></div><div v-if="canUpload&&detail.prepared.length" class="care-prepared"><strong>本人为此就诊准备、尚未归档</strong><button v-for="p in detail.prepared" :key="p.file_id" class="b-button outline small" @click="open('prepared',p)">继续确认归档 {{p.file_id.slice(0,8)}}</button></div></section>
 <ImageHistoryPanel v-if="has('image.read')" :visit-id="detail.visit.id" :context-key="detail.images.map((i:any)=>i.image_id+':'+i.row_version).join(',')" @denied="historyDenied"/>
 <section v-if="has('lab.read')" class="b-card c-block"><div class="f-list-head"><div><h2><FlaskConical :size="19"/>义齿加工订单</h2><p>医生提出要求和临床核对，护士登记交接与进度。</p></div><button v-if="has('lab.request')" class="b-button small" :disabled="busy||!!pending||!detail.treatments.length" @click="open('requirement')"><Plus :size="15"/>新建加工要求</button></div><p v-if="!detail.labs.length" class="b-empty">当前无加工订单。须先有医生确认的实际治疗。</p><article v-for="o in detail.labs" :key="o.lab_order_id" class="care-order"><div class="care-order-head"><div><small>订单 {{o.lab_order_id.slice(0,8).toUpperCase()}} · 版本 {{o.version}}</small><h3>{{o.lab_party}}</h3></div><span class="b-pill" :class="o.state==='usable'?'active':''">{{stateText[o.state]}}</span></div><p class="care-requirement">要求第 {{o.requirement?.version_no}} 版：{{o.requirement?.requirement_text}}</p><div class="care-facts"><span>当前预计返回 <strong>{{full(o.current_expected_return_at)}}</strong></span><span>正确接收 <strong>{{o.received?full(o.received.occurred_at):'尚无当前有效依据'}}</strong></span></div><p v-if="o.progress_pending_note" class="care-note">进度 / 问题：{{o.progress_pending_note}}</p><p v-if="o.has_open_usability_issue" class="c-pending">存在未解可用性问题，普通进度更新不会关闭。</p><div class="care-actions"><button v-if="has('lab.request')" class="b-button outline small" :disabled="busy||!!pending" @click="open('requirement',o)">更正加工要求</button><button v-if="has('lab.handover')||has('lab.progress')||has('lab.review')||has('lab.problem')" class="b-button small" :disabled="busy||!!pending||o.state==='requirement_changed'" @click="open('lab',o)">登记阶段 / 问题</button></div><LabHistoryPanel :visit-id="detail.visit.id" :order-id="o.lab_order_id" :version="o.version" :requirements-total="o.requirementsTotal" :handovers-total="o.handoversTotal" :reviews-total="o.reviewsTotal" @denied="historyDenied"/></article></section></template>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog care-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭影像加工办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">IMAGING / LAB COLLABORATION</div><h2>{{{image:form.imageId?'更正影像归档':'准备并确认影像归档',preview:'受控影像查看',requirement:'医生明确加工要求',lab:'登记加工阶段与问题'}[mode]}}</h2><div v-if="detail" class="f-context">{{detail.visit.patientName}} · {{detail.visit.doctorName}}</div><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='image'"><template v-if="form.imageId"><label>目标就诊患者姓名<input v-model="targets.search.value" maxlength="100" placeholder="同日同诊所内按姓名查询" :disabled="!!file||busy||!!pending" @input="form.targetVisitId=detail.visit.id;form.identityConfirmed=false"/></label><div class="care-actions"><button type="button" class="b-button outline small" :disabled="!!file||busy||targets.loading.value||!!pending" @click="findTargets()">查询归档目标</button><button v-if="targets.next.value" type="button" class="b-button outline small" :disabled="!!file||busy||targets.loading.value||targets.dirty.value||!!pending" @click="findTargets(true)">继续加载归档目标</button></div><p class="b-help">目标目录已加载 {{targets.items.value.length}} / {{targets.total.value}} 次。可继续加载其他页；候选仅供核对，保存时仍重新核权。</p><p v-if="targets.error.value" class="b-alert error">{{targets.error.value}}</p></template><label>归档实际就诊<select v-model="form.targetVisitId" :disabled="!!file||!form.imageId||targets.loading.value||targets.dirty.value" @change="form.identityConfirmed=false"><option :value="detail.visit.id">{{detail.visit.patientName}} · {{detail.visit.doctorName}} · {{full(detail.visit.arrivedAt)}} · 当前原就诊</option><option v-for="v in targets.items.value.filter((x:any)=>x.id!==detail.visit.id&&x.canImage)" :key="v.id" :value="v.id">{{v.patientName}} · {{v.doctorName}} · {{full(v.arrivedAt)}} · {{v.id.slice(0,8)}}</option></select></label><div class="b-two-fields"><label>类别<select v-model="form.imageType"><option v-if="has('image.photo')" value="photo">诊疗照片</option><option v-if="has('image.scan')" value="scan">检查影像</option></select></label><label>实际形成时间<input type="datetime-local" step="1" v-model="form.formedAt" required/></label></div><label>选择文件<input type="file" :disabled="busy||!!pending" accept="image/png,image/jpeg" @change="selectedFile"/></label><p class="b-help">PNG/JPEG，≤10MiB、≤2400万像素；仅用合成资料。先准备并校验，确认后才进入目录。</p><button type="button" class="b-button outline full" :disabled="!file||busy" @click="prepare">{{busy?'准备中…':'准备文件并读取预览'}}</button><div v-if="previewUrl" class="care-preview"><img :src="previewUrl" alt="归档前核对的影像内容" @error="previewVerified=false;error='浏览器无法显示图片，请勿确认归档。'"/></div><label>说明<textarea v-model="form.description" rows="2" maxlength="1000"/></label><label v-if="form.imageId">更正原因<textarea v-model="form.reason" required rows="2"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.duplicateConfirmed"/><span>如提示相同内容，已核实确需再归档，不将重复上传误作新影像。</span></label><label class="b-checkbox"><input type="checkbox" v-model="form.identityConfirmed" required/><span>已核对上方归档患者、实际就诊和文件预览，确认关联正确。</span></label></template>
 <template v-if="mode==='preview'"><div v-if="previewUrl" class="care-preview"><img :src="previewUrl" alt="本次授权读取的影像" @error="previewVerified=false;error='浏览器当前无法显示该影像。'"/></div><p v-else class="b-help">当前尚未成功读取影像。</p><button class="b-button outline full" type="button" :disabled="busy||!previewVerified" @click="download(form.imageId)">重新核权并下载</button></template>
 <template v-if="mode==='requirement'"><label>对应实际治疗<select v-model="form.treatmentId" :disabled="!!form.orderId" required><option value="">请选择医生已确认的实际治疗</option><option v-for="t in detail.treatments" :key="t.id" :value="t.id">{{t.name}} · {{full(t.performedAt)}} · 版本 {{t.version}}</option></select></label><label>实际加工方<input v-model="form.labParty" required maxlength="200"/></label><label>医生明确的加工要求<textarea v-model="form.requirementText" required rows="4" maxlength="4000"/></label><label>预计返回（可不填）<input type="datetime-local" step="1" v-model="form.expectedReturnAt"/></label><label v-if="form.orderId">更正原因<textarea v-model="form.reason" required rows="2"/></label><p class="b-help">更正要求后须按新要求重新取得接收和临床核对依据，旧事实保留；不由护士推定要求。</p></template>
 <template v-if="mode==='lab'"><p class="care-requirement">当前要求：{{form.order.requirement.requirement_text}}</p><label>实际办理动作<select v-model="form.action" required><option value="">请选择本次真实动作</option><option v-if="has('lab.handover')" value="sent">登记实际送出</option><option v-if="has('lab.progress')" value="progress">更新进度 / 延期</option><option v-if="has('lab.handover')" value="received">登记实际接收</option><option v-if="has('lab.review')&&form.order.received" value="review">医生临床核对</option><option v-if="has('lab.problem')" value="problem">登记问题 / 依据失效</option></select></label><label v-if="['sent','received','review'].includes(form.action)">实际发生时间<input type="datetime-local" step="1" v-model="form.occurredAt" required/></label><label v-if="form.action==='progress'">当前预计返回（可空）<input type="datetime-local" step="1" v-model="form.expectedReturnAt"/></label><label v-if="form.action==='received'">患者、数量、加工件与当前要求是否相符<select v-model="form.matchesRequirement" required><option value="unknown">尚未核实相符</option><option value="yes">已核实相符</option><option value="no">存在不相符问题</option></select></label><label v-if="form.action==='review'">医生临床核对结论<select v-model="form.isUsable" required><option value="">请明确选择</option><option value="yes">当前要求与接收依据下可用</option><option value="no">不可用 / 待重处理</option></select></label><label>真实交接内容、进度或核对结论<textarea v-model="form.content" required rows="3" maxlength="4000"/></label><template v-if="form.action==='review'&&form.order.has_open_usability_issue"><label class="b-checkbox"><input type="checkbox" v-model="form.resolveIssues"/><span>医生已核实原问题解决，明确重新判断临床可用性。</span></label><label>问题解决核实依据<textarea v-model="form.resolution" :required="form.isUsable==='yes'" rows="2"/></label></template><label v-if="form.action==='problem'" class="b-checkbox"><input type="checkbox" v-model="form.invalidateReceipt"/><span>当前接收依据本身失效，需要重新交接核对。未勾选则保留真实正确接收，仅撤销临床可用。</span></label><p class="b-help">实际接收、临床可用、复诊预约和实际装戴分别办理。本操作不自动约复诊或生成装戴治疗。</p></template>
 <button v-if="pending" type="button" class="b-button full" :disabled="busy" @click="send(pending.path,pending.body,pending.label)">核实原提交</button><button v-else-if="mode!=='preview'" class="b-button full" :disabled="busy||(mode==='image'&&(!form.fileId||!previewVerified))">{{busy?'正在保存…':mode==='image'?'确认归档':mode==='requirement'?'确认保存医生要求':'确认保存本次阶段'}}</button>
 </form></div>
</div></template>


